    ");
            WriteLiteral(@"@media (max-width: 480px) {
        .settings-grid {
            grid-template-columns: 1fr;
        }
    }

    .settings-card {
        background: var(--card-bg);
        border-radius: 16px;
        padding: 24px;
        display: flex;
        gap: 16px;
        box-shadow: var(--shadow);
        transition: transform 0.2s, box-shadow 0.2s;
    }

    .settings-card:hover {
        transform: translateY(-2px);
        box-shadow: var(--shadow-lg);
    }

    .settings-icon {
        width: 48px;
        height: 48px;
        border-radius: 12px;
        background: var(--bg-color);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 24px;
        flex-shrink: 0;
    }

    .settings-content {
        flex: 1;
    }

    .settings-content h2 {
        font-size: 18px;
        margin-bottom: 4px;
    }

